function validate([word]) {
  if (typeof word !== 'string' || word.length < 2 || word.length > 300) return 'word needs 2 to 300 letters.';
  if (!/^[A-Z]+$/.test(word)) return 'word may contain only uppercase English letters.';
  return null;
}

