function minimumDistance(word) {
  const FREE = 26;
  const distance = (from, to) => {
    if (from === FREE) return 0;
    return Math.abs(Math.floor(from / 6) - Math.floor(to / 6)) + Math.abs((from % 6) - (to % 6));
  };
  const letters = Array.from(word, ch => ch.charCodeAt(0) - 65);
  const n = letters.length;
  const dp = Array.from({ length: n }, () => new Array(FREE + 1).fill(Infinity));
  dp[0][FREE] = 0;

  for (let i = 0; i + 1 < n; i++) {
    const current = letters[i];
    const next = letters[i + 1];
    for (let other = 0; other <= FREE; other++) {
      const cost = dp[i][other];
      if (cost === Infinity) continue;
      const moveSame = cost + distance(current, next);
      dp[i + 1][other] = Math.min(dp[i + 1][other], moveSame);
      const moveOther = cost + distance(other, next);
      dp[i + 1][current] = Math.min(dp[i + 1][current], moveOther);
    }
  }
  return Math.min(...dp[n - 1]);
}

