function minimumDistance(word) {
  const rows = ['ABCDEF', 'GHIJKL', 'MNOPQR', 'STUVWX', 'YZ'];
  const where = {};
  rows.forEach((row, r) => [...row].forEach((ch, c) => { where[ch] = [r, c]; }));
  const gap = (a, b) => Math.abs(where[a][0] - where[b][0]) + Math.abs(where[a][1] - where[b][1]);
  // Search over the exact keys of both fingers (null = not placed yet), trying both fingers for every letter.
  const memo = new Map();
  const solve = (i, f1, f2) => {
    if (i === word.length) return 0;
    const key = i + ',' + f1 + ',' + f2;
    if (memo.has(key)) return memo.get(key);
    const ch = word[i];
    const useFirst = (f1 === null ? 0 : gap(f1, ch)) + solve(i + 1, ch, f2);
    const useSecond = (f2 === null ? 0 : gap(f2, ch)) + solve(i + 1, f1, ch);
    const best = Math.min(useFirst, useSecond);
    memo.set(key, best);
    return best;
  };
  return solve(0, null, null);
}

