function generate(rand, size) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  if (size === 'large') {
    let word = '';
    for (let i = 0; i < 300; i++) word += alphabet[Math.floor(rand() * 26)];
    return [word];
  }
  const n = 2 + Math.floor(rand() * 9);
  let pool = alphabet;
  if (rand() < 0.4) {
    // A few repeated letters make zero-cost presses and finger swaps common.
    pool = '';
    const k = 1 + Math.floor(rand() * 3);
    for (let j = 0; j < k; j++) pool += alphabet[Math.floor(rand() * 26)];
  }
  let word = '';
  for (let i = 0; i < n; i++) word += pool[Math.floor(rand() * pool.length)];
  return [word];
}
